//! `KubiosParams::threshold_floor_s` (absolute floor on Th1 / Th2) and `alpha`.
//!
//! Reference: `tests/data/kubios_floor_reference.json`, generated by `tools/exclusion_reference.py`
//! with the Python research port of fast-hrv v0.5.0 Kubios (`ektopi_kubios.py`, validated bit for bit
//! against `fix_positions_with`) on **synthetic** beat series only. The port's default variant is
//! v0.5.0 behaviour, so the default rows also pin that `threshold_floor_s = 0` changes nothing.

use fast_hrv::peaks::{
    Artifacts, KubiosParams, detect_artifacts, detect_artifacts_positions, fix_peaks_with,
    fix_positions_with,
};
use serde_json::Value;

fn load(name: &str) -> Value {
    let path = format!("{}/tests/data/{name}", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&text).unwrap()
}

fn f64s_from_bits(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| f64::from_bits(x.as_u64().unwrap()))
        .collect()
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as usize)
        .collect()
}

/// Output positions from the fixture's delta encoding (input minus `removed`, plus `added`, merged
/// by position).
fn from_delta(input: &[f64], d: &Value) -> Vec<f64> {
    let removed = usizes(&d["removed"]);
    let mut out: Vec<f64> = input
        .iter()
        .enumerate()
        .filter(|(i, _)| !removed.contains(i))
        .map(|(_, &p)| p)
        .collect();
    for a in d["added"].as_array().unwrap() {
        out.push(f64::from_bits(a[1].as_u64().unwrap()));
    }
    out.sort_by(f64::total_cmp);
    assert_eq!(out.len(), d["n"].as_u64().unwrap() as usize);
    out
}

fn same_bits(a: &[f64], b: &[f64]) -> bool {
    a.len() == b.len() && a.iter().zip(b).all(|(x, y)| x.to_bits() == y.to_bits())
}

fn artifacts_of(v: &Value) -> Artifacts {
    Artifacts {
        ectopic: usizes(&v["ectopic"]),
        missed: usizes(&v["missed"]),
        extra: usizes(&v["extra"]),
        longshort: usizes(&v["longshort"]),
    }
}

/// Python reference (synthetic): first-pass flags and fully corrected positions for alpha 5.2 / 6
/// and floors 0 / 30 / 40 / 50 ms, bit for bit.
#[test]
fn floor_and_alpha_match_python_reference() {
    let r = load("kubios_floor_reference.json");
    let (mut n, mut flags_default, mut flags_floor40) = (0, 0, 0);
    for case in r["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let fs = case["sampling_rate"].as_f64().unwrap();
        let pos = f64s_from_bits(&case["positions"]);
        for (vname, v) in case["variants"].as_object().unwrap() {
            let params = KubiosParams {
                alpha: v["alpha"].as_f64().unwrap(),
                threshold_floor_s: v["floor_s"].as_f64().unwrap(),
                ..Default::default()
            };
            let first = detect_artifacts_positions(&pos, fs, &params);
            assert_eq!(first, artifacts_of(&v["first_pass"]), "{name} {vname}");
            let fixed = fix_positions_with(&pos, fs, &params).unwrap();
            let expected = from_delta(&pos, &v["fixed"]);
            assert!(
                same_bits(&fixed.positions, &expected),
                "{name} {vname}: corrected positions differ"
            );
            assert_eq!(
                fixed.passes.len(),
                v["n_passes"].as_u64().unwrap() as usize,
                "{name} {vname}"
            );
            n += 1;
            match vname.as_str() {
                "default" => flags_default += first.total_count(),
                "floor40_alpha6" => flags_floor40 += first.total_count(),
                _ => {}
            }
        }
    }
    eprintln!(
        "Python reference: {n} (series, variant) pairs identical; first-pass flags default {flags_default}, floor 40 ms + alpha 6 {flags_floor40}"
    );
    assert!(n >= 50);
}

/// The default floor (0) and any non-positive floor do not touch the algorithm: NeuroKit2 Kubios
/// fixtures still match exactly (first pass and corrected peaks).
#[test]
fn zero_or_negative_floor_keeps_neurokit_parity() {
    let r = load("neurokit_kubios.json");
    assert_eq!(KubiosParams::default().threshold_floor_s, 0.0);
    assert_eq!(KubiosParams::default().alpha, 5.2);
    for floor in [0.0, -0.0, -0.05] {
        let params = KubiosParams {
            threshold_floor_s: floor,
            ..Default::default()
        };
        for case in r["cases"].as_array().unwrap() {
            let name = case["name"].as_str().unwrap();
            let fs = case["sampling_rate"].as_f64().unwrap();
            let peaks = usizes(&case["peaks"]);
            assert_eq!(
                detect_artifacts(&peaks, fs, &params),
                artifacts_of(&case["first_pass"]),
                "{name} floor {floor}"
            );
            let fixed = fix_peaks_with(&peaks, fs, &params).unwrap();
            assert_eq!(fixed.peaks, usizes(&case["fixed"]), "{name} floor {floor}");
        }
    }
}

// ---------------------------------------------------------------------------------------------
// synthetic low-HRV series
// ---------------------------------------------------------------------------------------------

struct Lcg(u64);
impl Lcg {
    fn uniform(&mut self) -> f64 {
        self.0 = self
            .0
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        ((self.0 >> 11) as f64 + 0.5) / (1u64 << 53) as f64
    }
    fn normal(&mut self) -> f64 {
        let (u, v) = (self.uniform(), self.uniform());
        (-2.0 * u.ln()).sqrt() * (2.0 * std::f64::consts::PI * v).cos()
    }
}

/// Very regular sinus rhythm (mean RR 600 ms, RSA 3 ms, noise 1.5 ms: RMSSD ≈ 3 ms) with small
/// fiducial jitter (±8–15 ms) on ~3 % of the beats. Positions in samples at 512 Hz.
fn low_hrv_series(seed: u64, n: usize) -> Vec<f64> {
    let fs = 512.0;
    let mut rng = Lcg(seed);
    let mut t = 0.0;
    let mut times = Vec::with_capacity(n);
    for _ in 0..n {
        let rr =
            0.600 + 0.003 * (2.0 * std::f64::consts::PI * 0.25 * t).sin() + 0.0015 * rng.normal();
        t += rr;
        times.push(t);
    }
    let mut pos: Vec<f64> = times.iter().map(|t| 1000.0 + t * fs).collect();
    for p in &mut pos[2..n - 2] {
        if rng.uniform() < 0.03 {
            let sign = if rng.uniform() < 0.5 { -1.0 } else { 1.0 };
            *p += sign * (0.008 + 0.007 * rng.uniform()) * fs;
        }
    }
    pos
}

/// A positive floor stops Kubios from flagging small jitter on a low-HRV series, where the quartile
/// thresholds are only a few milliseconds; the default flags it.
#[test]
fn positive_floor_reduces_flags_on_low_hrv() {
    let fs = 512.0;
    let (mut total0, mut total30) = (0, 0);
    for seed in 0..5 {
        let pos = low_hrv_series(seed, 400);
        let base = KubiosParams::default();
        let floored = KubiosParams {
            threshold_floor_s: 0.030,
            ..base
        };
        let f0 = detect_artifacts_positions(&pos, fs, &base).total_count();
        let f30 = detect_artifacts_positions(&pos, fs, &floored).total_count();
        let c0 = fix_positions_with(&pos, fs, &base).unwrap().changed_count();
        let c30 = fix_positions_with(&pos, fs, &floored)
            .unwrap()
            .changed_count();
        eprintln!("seed {seed}: first-pass flags {f0} -> {f30}, changed beats {c0} -> {c30}");
        assert!(f30 <= f0, "seed {seed}");
        total0 += f0;
        total30 += f30;
    }
    assert!(total0 >= 20, "default should flag the jitter ({total0})");
    assert!(total30 * 4 <= total0, "floor 30 ms: {total30} vs {total0}");
}

/// `alpha` is a plain parameter: a larger multiplier never adds flags on these series.
#[test]
fn alpha_is_configurable() {
    let fs = 512.0;
    let pos = low_hrv_series(7, 400);
    let f52 = detect_artifacts_positions(&pos, fs, &KubiosParams::default()).total_count();
    let p6 = KubiosParams {
        alpha: 6.0,
        ..Default::default()
    };
    let f6 = detect_artifacts_positions(&pos, fs, &p6).total_count();
    eprintln!("alpha 5.2: {f52} flags, alpha 6.0: {f6} flags");
    assert!(f6 <= f52);
}
